ime:date_format(new Date(child.lastModified()),\"yyyy-MM-dd HH:mm:ss\"),\r\n            downloadPath:\"/admin/file/download/\"+dir+\"/\"+child.getName(),\r\n            size:sizeStr(child.length()),\r\n            length:child.length(),\r\n            contentType:Files.probeContentType(Paths.get(child.getPath()))\r\n        })\r\n    }\r\n}\r\n\r\nreturn items'),('magic-api/api/admin/流程/', 'this is directory'),('magic-api/api/admin/流程/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"be084bec4cdf44d0a598edaf5f56b692\",\r\n  \"name\" : \"流程\",\r\n  \"type\" : \"api\",\r\n  \"parentId\" : \"47dc323d68af4fb4836d625d88f01bd4\",\r\n  \"path\" : \"/jqpFlow\",\r\n  \"createTime\" : 1719555477555,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}'),('magic-api/api/admin/流程/启动流程.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"7d78efca30944e67940988b50547df2d\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"be084bec4cdf44d0a598edaf5f56b692\",\r\n  \"name\" : \"启动流程\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1720064497614,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/start/{code}/{id}/{name}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ {\r\n    \"name\" : \"code\",\r\n    \"value\" : \"test01\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"id\",\r\n    \"value\" : \"1\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"name\",\r\n    \"value\" : \"测试\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"responseBody\" : \"{\\n    \\\"status\\\": 0,\\n    \\\"msg\\\": \\\"success\\\",\\n    \\\"data\\\": \\\"ok\\\"\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"status\",\r\n      \"value\" : \"0\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"msg\",\r\n      \"value\" : \"success\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"data\",\r\n      \"value\" : \"ok\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport org.ssssssss.script.MagicScriptContext\r\nimport \'@/flow/getFlowContext\' as getFlowContext;\r\nimport \'@/flow/getNextNode\' as getNextNode;\r\nimport \'@/flow/getCandidateUserIds\' as getCandidateUserIds;\r\nimport \'@/flow/createNextTask\' as createNextTask;\r\nimport \'@/session/getUser\' as getUser;\r\nimport \'@/db/saveOrUpdate\' as saveOrUpdate;\r\nimport cn.hutool.core.util.IdUtil;\r\nimport magic;\r\nimport log;\r\nlet userId = getUser();\r\nlet user = db.selectOne(\"select * from jqp_user where id = #{userId}\")\r\n\r\nlet flow = db.selectOne(\"select * from jqp_flow where code = #{code}\");\r\nif(flow == null){\r\n    exit 9, \"流程编号错误\";\r\n}\r\nlet flowContext = getFlowContext(flow.graph_data);\r\n\r\n//return flowContext;\r\n// 查询未结束的流程实例\r\nlet flow_instance = db.selectOne(\"\"\"\r\n    select * from jqp_flow_instance instance \r\n    where flow_id = #{flow.id} \r\n    and ref_id = #{id} \r\n    and end_time is null \r\n\"\"\")\r\n\r\n//当前节点\r\nlet curNode = null;\r\nlet curTask = null;\r\n\r\nlet obj = db.selectOne(`select * from ${flow.table_name} where id = #{id}`)\r\n\r\n\r\nlet context = {\r\n    obj:obj,\r\n    name:name\r\n};\r\nlet nodeStatus = flowContext.startNode.properties.status;\r\nlet objStatus = obj[flow.status_field];\r\n\r\nlet nodeStatusList = Arrays.asList(nodeStatus.split(\",\"));\r\n\r\nif(not_blank(nodeStatus) && nodeStatusList.indexOf(objStatus)<0){\r\n\r\n    let nodeStatusNames = db.select( \"\"\"\r\n        select di.name from jqp_dic d,jqp_dic_item di \r\n        where d.code = #{flow.status_dic}\r\n        and d.id = di.dic_id\r\n        and di.value in (#{nodeStatusList})\r\n    \r\n    \"\"\").map(item->item.name).join(\",\");\r\n\r\n    exit 9, `只有[${nodeStatusNames}]才能发起流程`;\r\n}\r\n\r\ndb.transaction(()->{\r\n    if(flow_instance == null){\r\n        //新流程,找到开始节点\r\n        curNode = flowContext.startNode;\r\n\r\n        flow_instance = {\r\n            flow_id:flow.id,\r\n            name:name,\r\n            ref_id:id,\r\n            start_time:now(),\r\n            create_user_id:user.id,\r\n            create_user_name:user.name\r\n        };\r\n        saveOrUpdate(\'jqp_flow_instance\',flow_instance);\r\n\r\n        log.info(\"curNode:{}\",curNode);\r\n        \r\n        curTask = {\r\n            flow_instance_id:flow_instance.id,\r\n            task_name:curNode.text.value,\r\n            task_id:curNode.id,\r\n            start_time:now(),\r\n            candidate_user_ids:getCandidateUserIds(curNode,flow_instance,context),\r\n            page_code:curNode.properties.page\r\n        };\r\n        saveOrUpdate(\'jqp_flow_instance_task\',curTask);\r\n        flow_instance.current_task_id = curTask.id;\r\n        flow_instance.current_task_name = curTask.task_name;\r\n        saveOrUpdate(\'jqp_flow_instance\',flow_instance);\r\n        \r\n    }else{\r\n\r\n        curTask = db.selectOne(\"\"\"\r\n            select * from jqp_flow_instance_task \r\n            where flow_instance_id = #{flow_instance.id}\r\n            and id = #{flow_instance.current_task_id}\r\n        \"\"\")\r\n        curNode = flowContext.nodeMap[curTask.task_id];\r\n    }\r\n\r\n    let edge = flowContext.edgeMap[curNode.id][0];\r\n\r\n    let nextNode = flowContext.nodeMap[edge.targetNodeId]\r\n    let nextNodeData = getNextNode(nextNode,flowContext,context,edge);\r\n    nextNode = nextNodeData.node;\r\n    let nextNodeEdge = nextNodeData.node;\r\n\r\n    log.info(\"edgeIds:{}\",nextNodeData.edgeIds);\r\n\r\n    //完成任务\r\n    curTask.end_time = now();\r\n    curTask.edge_id = nextNodeData.edgeIds;\r\n    curTask.edge_name = nextNodeData.edgeNames;\r\n    curTask.audit_user_id = userId;\r\n\r\n    saveOrUpdate(\'jqp_flow_instance_task\',curTask);\r\n\r\n    \r\n    \r\n    //更新状态\r\n    if(nextNodeEdge && not_blank(nextNodeEdge.properties.status)){\r\n        obj[flow.status_field] = nextNodeEdge.properties.status;\r\n        saveOrUpdate(flow.table_name,obj);\r\n    }\r\n\r\n    createNextTask(nextNode,flow_instance);\r\n})\r\n\r\n\r\nreturn \'ok\''),('magic-api/api/admin/流程/完成任务.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"87d93863ec3c440cae09bac287d710e1\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"be084bec4cdf44d0a598edaf5f56b692\",\r\n  \"name\" : \"完成任务\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1720059670228,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/completeTask/{taskId}/{edgeId}\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ {\r\n    \"name\" : \"taskId\",\r\n    \"value\" : \"1808051530412568576\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"edgeId\",\r\n    \"value\" : \"Flow_34sb22l\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"responseBody\" : \"{\\n    \\\"status\\\": 0,\\n    \\\"msg\\\": \\\"success\\\",\\n    \\\"data\\\": {\\n        \\\"edge\\\": {\\n            \\\"id\\\": \\\"Flow_34sb22l\\\",\\n            \\\"type\\\": \\\"JqpSequenceFlow\\\",\\n            \\\"sourceNodeId\\\": \\\"Activity_33fpbe2\\\",\\n            \\\"targetNodeId\\\": \\\"Event_0qoelp4\\\",\\n            \\\"startPoint\\\": {\\n                \\\"x\\\": 1130,\\n                \\\"y\\\": 520\\n            },\\n            \\\"endPoint\\\": {\\n                \\\"x\\\": 1340,\\n                \\\"y\\\": 378\\n            },\\n            \\\"properties\\\": {\\n 