" : \"Object\",\r\n          \"type\" : null,\r\n          \"defaultValue\" : null,\r\n          \"validateType\" : \"\",\r\n          \"error\" : \"\",\r\n          \"expression\" : \"\",\r\n          \"children\" : [ ]\r\n        } ]\r\n      }, {\r\n        \"name\" : \"nextNode\",\r\n        \"value\" : \"null\",\r\n        \"description\" : \"\",\r\n        \"required\" : false,\r\n        \"dataType\" : \"Object\",\r\n        \"type\" : null,\r\n        \"defaultValue\" : null,\r\n        \"validateType\" : \"\",\r\n        \"error\" : \"\",\r\n        \"expression\" : \"\",\r\n        \"children\" : [ ]\r\n      } ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport \'@/flow/getFlowContext\' as getFlowContext;\r\nimport \'@/flow/getNextNode\' as getNextNode;\r\nimport \'@/flow/createNextTask\' as createNextTask;\r\nimport \'@/db/saveOrUpdate\' as saveOrUpdate;\r\nimport \'@/session/getUser\' as getUser;\r\nimport log;\r\nlet userId = getUser();\r\nlet user = db.selectOne(\"select * from jqp_user where id = #{userId}\")\r\n\r\n\r\nlet task = db.selectOne(\"select * from jqp_flow_instance_task where id = #{taskId}\")\r\nlet flow_instance = db.selectOne(\"select * from jqp_flow_instance where id = #{task.flow_instance_id}\")\r\nlet flow =  db.selectOne(\"select * from jqp_flow where id = #{flow_instance.flow_id}\")\r\n\r\nlet obj = db.selectOne(`select * from ${flow.table_name} where id = #{flow_instance.ref_id}`)\r\n\r\n\r\nlet flowContext = getFlowContext(flow.graph_data);\r\nlet edges = flowContext.edgeMap[task.task_id];\r\nlet edge = edges.filter(item->item.id == edgeId)[0];\r\nlet node = flowContext.nodeMap[task.task_id];\r\n\r\ndb.transaction(()->{\r\n\r\n    task.end_time = now();\r\n    task.edge_id = edge.id;\r\n    task.edge_name = edge.text.value;\r\n    task.audit_user_id = userId;\r\n    task.files = body.files;\r\n    task.remark = body.remark;\r\n    task.imgs = body.imgs;\r\n    saveOrUpdate(\'jqp_flow_instance_task\',task);\r\n    let flag = true;\r\n    if(node.properties.checkType == \"任意成员审核通过\"){\r\n        \r\n    }else if(node.properties.checkType == \"全部成员审核通过\"){\r\n        let tasks = db.select(\"\"\"\r\n            select * from jqp_flow_instance_task \r\n            where flow_instance_id = #{task.flow_instance_id} \r\n            and jointly_sign_id = #{task.jointly_sign_id}\r\n        \"\"\");\r\n        \r\n        for(index,item in tasks){\r\n            if(item.end_time == null){\r\n                flag = false;\r\n            }\r\n        }\r\n        if(flag){\r\n            for(index,item in tasks){\r\n                item.jointly_sign_complete_time = now();\r\n                saveOrUpdate(\'jqp_flow_instance_task\',item);\r\n            }\r\n        }\r\n    }\r\n\r\n    if(!flag){\r\n        return \"等待其他人会签完成\";\r\n    }\r\n\r\n\r\n    let nextNode = flowContext.nodeMap[edge.targetNodeId];\r\n    let context = {\r\n        obj:obj,\r\n        name:flow_instance.name\r\n    };\r\n\r\n    let nextNodeData = getNextNode(nextNode,flowContext,context,edge);\r\n    let nextNode = nextNodeData.node;\r\n    let nextNodeEdge = nextNodeData.edge;\r\n\r\n    if(task.edge_id != nextNodeData.edgeIds){\r\n        task.edge_id = nextNodeData.edgeIds;\r\n        task.edge_id = nextNodeData.edgeNames;\r\n\r\n        saveOrUpdate(\'jqp_flow_instance_task\',task);\r\n    }\r\n    log.info(\"更新状态:{}\",nextNodeEdge);\r\n    //更新状态\r\n    if(nextNodeEdge && not_blank(nextNodeEdge.properties.status)){\r\n        obj[flow.status_field] = nextNodeEdge.properties.status;\r\n        saveOrUpdate(flow.table_name,obj);\r\n    }\r\n\r\n    if(nextNode == null){\r\n        //流程结束\r\n        flow_instance.end_time = now();\r\n        flow_instance.current_task_id = null;\r\n        flow_instance.current_task_name = null;\r\n        saveOrUpdate(\"jqp_flow_instance\",flow_instance,context);\r\n    }else{\r\n        createNextTask(nextNode,flow_instance);\r\n    }\r\n});\r\n\r\n\r\nreturn \"ok\"'),('