     \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : \"10\",\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"page\",\r\n      \"value\" : \"1\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : \"1\",\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  },\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'@/session/getUser\' as getUser;\r\nimport log;\r\n\r\nlet userId = getUser();\r\n\r\nlet adminCount = db.selectInt(\"\"\"\r\n    select count(*) from jqp_user u \r\n    left join jqp_role r on FIND_IN_SET(r.id,u.role_ids) > 0\r\n    where u.id = #{userId}\r\n    and r.code = \'admin\'\r\n\"\"\");\r\nlet whereSql = \"\";\r\n//log.info(\"userId:{}, count :{}\",userId,adminCount);\r\nif(adminCount != null && adminCount > 0){\r\n\r\n}else{\r\n    whereSql = \" and FIND_IN_SET(#{userId},t.candidate_user_ids) > 0  \"\r\n}\r\n\r\nlet page = db.page(`\r\n    select \r\n        f.table_name,\r\n        f.id flow_id,\r\n        f.name flow_name,\r\n        i.id flow_instance_id,\r\n        i.name flow_instance_name,\r\n        t.id,\r\n        t.task_name,\r\n        t.edge_name,\r\n        t.start_time,\r\n        t.end_time,\r\n        t.jointly_sign_complete_time,\r\n        i.ref_id,\r\n        case \r\n            when t.page_code is null or t.page_code = \'\'\r\n                then f.page_code\r\n            else t.page_code\r\n        end page_code,\r\n        t.files,\r\n        t.imgs,\r\n        t.remark\r\n\r\n    from jqp_flow_instance_task t \r\n    left join jqp_flow_instance i on i.id = t.flow_instance_id\r\n    left join jqp_flow f on f.id = i.flow_id \r\n\r\n    where \r\n    1=1 \r\n    \r\n    ${whereSql}\r\n    \r\n    order by t.start_time desc ,t.id desc \r\n`,body.perPage,(body.page-1)*body.perPage);\r\n\r\nreturn {\r\n    total:page.total,\r\n    items:page.list || []\r\n}'),('magic-api/api/admin/流程/流程详情.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"f21226ae60a9434da8eeeae35d68a1cb\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"be084bec4cdf44d0a598edaf5f56b692\",\r\n  \"name\" : \"流程详情\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1719996766753,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getFlowDetail\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ {\r\n    \"name\" : \"flowId\",\r\n    \"value\" : null,\r\n    \"description\" : \"流程id\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"flowInstanceId\",\r\n    \"value\" : null,\r\n    \"description\" : \"流程实例id\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.hutool.json.JSONUtil\r\nimport magic;\r\nimport \'@/flow/getFlowContext\' as getFlowContext;\r\nimport log;\r\nlet flow = db.selectOne(\"select * from jqp_flow where id = #{flowId}\");\r\nlet flowContext = getFlowContext(flow.graph_data);\r\nlet resp = {\r\n    readOnly:false,\r\n    showProperties:true,\r\n    graphData:not_blank(flow.graph_data) ?  JSONUtil.parseObj(flow.graph_data) :{},\r\n    statusOptions:magic.execute(\"get\",\"/admin/jqpDic/options/{code}\",{\r\n        code:flow.status_dic\r\n    })\r\n};\r\nif(not_blank(flowInstanceId)){\r\n    resp.readOnly = true;\r\n    resp.showProperties = false;\r\n\r\n    let flowInstance = db.selectOne(\"select * from jqp_flow_instance where id = #{flowInstanceId}\");\r\n    let tasks = db.select(\"select * from jqp_flow_instance_task where flow_instance_id = #{flowInstanceId}\");\r\n    let currentTask = tasks.filter(item->item.id == flowInstance.current_task_id);\r\n\r\n    //log.info(\"currentTask:{}\",currentTask);\r\n    //设置当前节点/流转\r\n    let currentNode = null;\r\n    let currentEdgeIds = [];\r\n    if(currentTask == null){\r\n        currentTask = flowContext.endNode;\r\n    }else{\r\n        currentNode = flowContext.nodeMap[currentTask.task_id];\r\n    }\r\n    //设置经过的节点/流转\r\n    let activeNodes = [];\r\n    let activeEdges = [];\r\n    for(index,task in tasks){\r\n        activeNodes.push(task.task_id);\r\n        if(task.edge_id){\r\n\r\n            let arr = task.edge_id.split(\",\");\r\n            for(_idx,eid in arr){\r\n                activeEdges.push(eid);\r\n            }\r\n            \r\n        }\r\n    }\r\n    for(index,node in resp.graphData.nodes){\r\n        if(activeNodes.contains(node.id)){\r\n            node.properties.active = \"true\";\r\n        }\r\n\r\n        if(currentNode != null && node.id == currentNode.id){\r\n            node.properties.current = \"true\";\r\n            currentEdgeIds = flowContext.edgeMap[node.id].map(item->item.id);\r\n        }\r\n    }\r\n    for(index,edge in resp.graphData.edges){\r\n        if(activeEdges.contains(edge.id)){\r\n            edge.properties.active = \"true\";\r\n        }\r\n        if(currentEdgeIds.contains(edge.id)){\r\n            edge.properties.current = \"true\";\r\n        }\r\n    }\r\n\r\n}\r\n\r\nreturn resp;'),('magic-api/api/admin/流程/获取下一步流转.ms', '{\r\n  \"properties\