ter_tree(\r\n        tree_field_map(\r\n            list_to_tree(list || [],treeId),\r\n            {\r\n                \"label\":\"name\"\r\n            }\r\n        ),\r\n        menuIds\r\n    );\r\n    let filterButtons = (items) => {\r\n        return items.filter(item=>{\r\n            item.children = filterButtons(item.children);\r\n            return item.is_button == \'no\'\r\n        })\r\n    }\r\n\r\n    let buttons = new HashSet();\r\n\r\n    let getButtons = (items) =>{\r\n        for(index,item in items){\r\n            if(item.is_button == \'yes\' && not_blank(item.auth_code)){\r\n\r\n                buttons.add(item.auth_code);\r\n            }\r\n            getButtons(item.children);\r\n        }\r\n    }\r\n    getButtons(tree);\r\n\r\n    let urls = new HashSet();\r\n\r\n    let getUrls = (items) =>{\r\n        for(index,item in items){\r\n            if(not_blank(item.url)){\r\n                urls.add(item.url);\r\n            }\r\n            if(not_blank(item.urls)){\r\n                let arr = item.urls.split(\"\\n\");\r\n                for(i,url in arr){\r\n                    if(not_blank(url)){\r\n                        urls.add(url)\r\n                    }\r\n                }\r\n            }\r\n            getUrls(item.children);\r\n        }\r\n    }\r\n    getUrls(tree);\r\n    urls.addAll(commonUrls());\r\n    return {\r\n        buttons:buttons,\r\n        urls:urls,\r\n        menus:filterButtons(tree),\r\n    }\r\n}\r\n\r\n\r\n\r\nreturn {\r\n    pc:getByType(\"pc\"),\r\n    mobile:getByType(\"mobile\"),\r\n    userId:userId\r\n};'),('magic-api/function/会话/设置用户.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"8489368035364209b6a4b95781dfbd97\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"c8909e0f38c74d11871708d55bcae5c3\",\r\n  \"name\" : \"设置用户\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1747377868999,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/setUser\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"user\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport request;\r\nimport \'@/session/getUserPermission\' as getUserPermission;\r\n\r\nif(not_null(user)){\r\n    request.get().getSession().setAttribute(\"login_user\",user.id)\r\n    request.get().getSession().setAttribute(\"user_session\",getUserPermission());\r\n}else{\r\n    request.get().getSession().setAttribute(\"login_user\",null);\r\n    request.get().getSession().setAttribute(\"user_session\",null);\r\n}\r\n\r\nreturn null;'),('magic-api/function/工具类/', 'this is directory'),('magic-api/function/工具类/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"工具类\",\r\n  \"type\" : \"function\",\r\n  \"parentId\" : \"0\",\r\n  \"path\" : \"/utils\",\r\n  \"createTime\" : 1716533486817,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}'),('magic-api/function/工具类/json转amis页面.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"1223f5b7f79f4425928c629242b82427\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"json转amis页面\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1720061435788,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"amis_page\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"json\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport cn.hutool.json.JSONUtil\r\nimport response;\r\n\r\nlet jsonStr = JSONUtil.toJsonPrettyStr(json);\r\n\r\nlet html = `\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"zh\">\r\n<head>\r\n    <meta charset=\"UTF-8\" />\r\n    <title>jqp-admin-v2低代码开发平台</title>\r\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n    <meta\r\n            name=\"viewport\"\r\n            content=\"width=device-width, initial-scale=1, maximum-scale=1\"\r\n    />\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=Edge\" />\r\n    <link rel=\"stylesheet\" href=\"/amis/sdk.css\" />\r\n    <link rel=\"stylesheet\" href=\"/amis/helper.css\" />\r\n    <link rel=\"stylesheet\" href=\"/amis/iconfont.css\" />\r\n\r\n    <!-- 这是默认主题所需的，如果是其他主题则不需要 -->\r\n    <!-- 从 1.1.0 开始 sdk.css 将不支持 IE 11，如果要支持 IE11 请引用这个 css，并把前面那个删了 -->\r\n    <!-- <link rel=\"stylesheet\" href=\"sdk-ie11.css\" /> -->\r\n    <!-- 不过 amis 开发团队几乎没测试过 IE 11 下的效果，所以可能有细节功能用不了，如果发现请报 issue -->\r\n    <style>\r\n        html,\r\n        body,\r\n        .app-wrapper {\r\n            position: relative;\r\n            width: 100%;\r\n            height: 100%;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n        .cxd-Tabs-pane{\r\n            padding:0px !important;\r\n        }\r\n        .cxd-FileControl .disabled .cxd-Button{\r\n            display: none !important;\r\n        }\r\n        .cxd-ImageControl .is-disabled .cxd-ImageControl-addBtn{\r\n            display: none !important;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div id=\"root\" class=\"app-wrapper\"></div>\r\n<script src=\"/amis/sdk.js\"></script>\r\n<script src=\"/amis/rest.js\"></script>\r\n<script src=\"/amis/tinymce.js\"></script>\r\n\r\n<script type=\"text/javascript\">\r\n    let amis_ = amisRequire(\'amis/embed\');\r\n    // 通过替换下面这个配置来生成不同页面\r\n    let AMIS_JSON = ${jsonStr};\r\n    window.amisScoped = amis_.embed(\'#root\', AMIS_JSON,{},{\r\n        responseAdaptor: function(api, response, query, request){\r\n            if(response.status == 1){\r\n                //需要登录;\r\n                //前后端不分离的\r\n                if(window.top){\r\n                    window.top.location.href=\"/\";\r\n                }else{\r\n                    window.location.href=\"/\";\r\n                }\r\n            }\r\n\r\n            return response;\r\n        }\r\n    });\r\n</script>\r\n</body>\r\n</html>\r\n\r\n\r\n`;\r\nresponse.setHeader(\"Content-Type\",\"text/html;charset=utf-8\")\r\n\r\nresponse.getOutputStream().write(html.getBytes(\"UTF-8\"))\r\n\r\nreturn response.end();'),('magic-api/function/工具类/列表转树.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"738aae35b78f4cdabc311f086752ef20\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"列表转树\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1717383649864,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/list_to_tree\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"list\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Collection\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"treeId\",\r\n    \"value\" : null,\r\n    \"description\" : \"需要过滤的节点\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nif(is_null(list)){\r\n    return [];\r\n}\r\nlet menuMap = {};\r\nlet parentIdMap = {};\r\nfor(index,item in list){\r\n    menuMap[item.id] = item;\r\n    item.children = [];\r\n    if(not_blank(item.parent_id)){\r\n        if(!parentIdMap.containsKey(item.parent_id)){\r\n            parentIdMap[item.parent_id] = [];\r\n        }\r\n        parentIdMap[item.parent_id].add(item);\r\n    }\r\n}\r\nlet roots = [];\r\nfor(index,item in list){\r\n    if(parentIdMap.containsKey(item.id)){\r\n        item.children = parentIdMap[item.id];\r\n    }\r\n    if(is_null(item.parent_id) || !menuMap.containsKey(item.parent_id)){\r\n        roots.add(item);\r\n    }\r\n}\r\n\r\nif(not_blank(treeId)){\r\n    let tree = menuMap[treeId]\r\n    if(not_null(tree)){\r\n        let parent = menuMap[tree.parent_id];\r\n        if(not_null(parent)){\r\n            parent.children.remove(tree);\r\n        }else{\r\n            roots.remove(tree);\r\n        }\r\n    }\r\n}\r\n\r\n\r\nreturn roots;'),('magic-api/function/工具类/匹配url.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"87b1fbe97a1d4de9a3fb93448f1ea3d5\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"匹配url\",\r\n  \"createTime\" : 1717379773214,\r\n  \"updateTime\" : null,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/matchUrl\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"url\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"patterns\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Collection\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport org.springframework.util.AntPathMatcher\r\n\r\nlet matcher = new AntPathMatcher();\r\n\r\nfor(index,pattern in patterns){\r\n    if(matcher.match(pattern,url)){\r\n        return true;\r\n    }\r\n}\r\nreturn false;'),('magic-api/function/工具类/树字段映射.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"copy1716792740618d56787\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"树字段映射\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1716793324633,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/tree_field_map\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"tree\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Collection\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"fieldMap\",\r\n    \"value\" : null,\r\n    \"description\" : \"字段映射\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Map\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\n\r\n\r\nlet fn = (list) ->{\r\n    if(is_null(list)){\r\n        return;\r\n    }\r\n    for(index,item in list){\r\n        for(key,value in fieldMap){\r\n            item[key] = item[value];\r\n        }\r\n        fn(item.children);\r\n    }\r\n}\r\n\r\nfn(tree);\r\n\r\nreturn tree;'),('magic-api/function/工具类/树过滤.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"7d9d9cc478df4cd3a9a3431c1e079cec\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d7286d9a91dc43f5a4e911c6055c0853\",\r\n  \"name\" : \"树过滤\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1718328835326,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"filter_tree\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"tree\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Collection\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"ids\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Collection\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport cn.hutool.json.JSONUtil\r\nimport log;\r\nlet fn = (obj) => {\r\n    if(ids.contains(obj.id)){\r\n        return true;\r\n    }\r\n    for(index,child in (obj.children || [])){\r\n        if(fn(child)){\r\n            return true;\r\n        }\r\n    }\r\n    return false;\r\n}\r\n\r\n//log.info(\"tree:{}\",JSONUtil.toJsonStr(tree))\r\nlet filter = (items) => {\r\n    if(is_null(items)){\r\n        return [];\r\n    }\r\n    let new_items = [];\r\n    for(index,item in items){\r\n        if(ids.contains(item.id)){\r\n            //如果父节点 在过滤里面,子节点直接不用判断,全部包含\r\n            new_items.add(item);\r\n        }else{\r\n            //如果子节点在里面,父节点也应该在里面\r\n            item.children = filter(item.children);\r\n            if(fn(item)){\r\n                new_items.add(item);\r\n            }\r\n        }\r\n    }\r\n    return new_items;\r\n}\r\n\r\nreturn filter(tree);'),('magic-api/function/数据库操作/', 'this is directory'),('magic-api/function/数据库操作/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"1ffd86f2e28f4ea38a292ff728ba51a7\",\r\n  \"name\" : \"数据库操作\",\r\n  \"type\" : \"function\",\r\n  \"parentId\" : \"0\",\r\n  \"path\" : \"db\",\r\n  \"createTime\" : 1716861742345,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}'),('magic-api/function/数据库操作/保存或更新.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"acd044960f1e485f95e02c676cc6e2bc\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1ffd86f2e28f4ea38a292ff728ba51a7\",\r\n  \"name\" : \"保存或更新\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1719816697980,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/saveOrUpdate\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"tableName\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"obj\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.util.Map\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport cn.hutool.core.util.IdUtil\r\n\r\nif(is_blank(obj.id::string)){\r\n    obj.id = IdUtil.getSnowflake().nextId();\r\n    db.camel().table(tableName).insert(obj)\r\n}else{\r\n    db.camel().table(tableName).primary(\"id\").update(obj,true)\r\n}\r\n\r\nreturn obj'),('magic-api/function/数据库操作/获取表列.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"909b9addd5fd4430ac63d8bf5c77f9d6\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1ffd86f2e28f4ea38a292ff728ba51a7\",\r\n  \"name\" : \"获取表列\",\r\n  \"createTime\" : 1716862654425,\r\n  \"updateTime\" : null,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getTableColumns\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"tableName\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nreturn \'Hello magic-api\''),('magic-api/function/流程/', 'this is directory'),('magic-api/function/流程/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"1761a7c600fd49088232dc2c96cfc70e\",\r\n  \"name\" : \"流程\",\r\n  \"type\" : \"function\",\r\n  \"parentId\" : \"0\",\r\n  \"path\" : \"/flow\",\r\n  \"createTime\" : 1719883673805,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}'),('magic-api/function/流程/开启下一个任务.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"eac52c744be24eafbb5fee68c09658ea\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1761a7c600fd49088232dc2c96cfc70e\",\r\n  \"name\" : \"开启下一个任务\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1720064533040,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/createNextTask\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"nextNode\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"flow_instance\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport \'@/flow/getCandidateUserIds\' as getCandidateUserIds;\r\nimport \'@/db/saveOrUpdate\' as saveOrUpdate;\r\n\r\n\r\nlet userIds = getCandidateUserIds(nextNode,flow_instance,context);\r\n\r\nif(nextNode.properties.checkType == \"任意成员审核通过\" || is_blank(userIds)){\r\n    //如果无人,就当成非会签任务\r\n    let nextTask = {\r\n        flow_instance_id:flow_instance.id,\r\n        task_name:nextNode.text.value,\r\n        task_id:nextNode.id,\r\n        start_time:now(),\r\n        candidate_user_ids:userIds,\r\n        page_code:nextNode.properties.page\r\n    };\r\n    saveOrUpdate(\'jqp_flow_instance_task\',nextTask);\r\n\r\n    flow_instance.current_task_id = nextTask.id;\r\n    flow_instance.current_task_name = nextTask.task_name;\r\n\r\n    saveOrUpdate(\'jqp_flow_instance\',flow_instance);\r\n\r\n}else if(nextNode.properties.checkType == \"全部成员审核通过\"){\r\n    let userList = userIds.split(\",\");\r\n    let jointly_sign_id = IdUtil.getSnowflake().nextId();\r\n\r\n    let nextTask = null;\r\n    for(index,uid in userList){\r\n        nextTask = {\r\n            flow_instance_id:flow_instance.id,\r\n            task_name:nextNode.text.value,\r\n            task_id:nextNode.id,\r\n            start_time:now(),\r\n            candidate_user_ids:uid,\r\n            jointly_sign_id:jointly_sign_id,\r\n            page_code:nextNode.properties.page\r\n        };\r\n        saveOrUpdate(\'jqp_flow_instance_task\',nextTask);\r\n    }\r\n\r\n    flow_instance.current_task_id = nextTask.id;\r\n    flow_instance.current_task_name = nextTask.task_name;\r\n\r\n    saveOrUpdate(\'jqp_flow_instance\',flow_instance);\r\n}\r\n'),('magic-api/function/流程/流程上下文.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"16e63a531d1143a0b0911da30aeed3ee\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1761a7c600fd49088232dc2c96cfc70e\",\r\n  \"name\" : \"流程上下文\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1719883685604,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getFlowContext\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"config\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport cn.hutool.json.JSONUtil\r\n\r\nconfig = JSONUtil.parseObj(config);\r\n\r\nlet nodes = config.nodes;\r\nlet edges = config.edges;\r\n\r\nlet startNode = null;\r\nlet endNode = null;\r\n\r\nlet nodeMap = {};\r\nlet edgeMap = {};\r\nfor(index,node in nodes){\r\n    if(node.type == \'JqpStart\'){\r\n        startNode = node;\r\n    }else if(node.type == \'JqpEnd\'){\r\n        endNode = node;\r\n    }\r\n    nodeMap[node.id] = node;\r\n}\r\nfor(index,edge in edges){\r\n    if(!edgeMap.containsKey(edge.sourceNodeId)){\r\n        edgeMap[edge.sourceNodeId] = [];\r\n    }\r\n    edgeMap[edge.sourceNodeId].push(edge);\r\n}\r\n\r\n\r\nreturn {\r\n    //开始节点后的第一个节点,作为开始节点\r\n    startNode:nodeMap[edgeMap[startNode.id][0].targetNodeId],\r\n    endNode,\r\n    nodeMap,\r\n    edgeMap\r\n};'),('magic-api/function/流程/获取下一个任务节点.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"6ab1603fd7c9423c9e6817f4485c54e6\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1761a7c600fd49088232dc2c96cfc70e\",\r\n  \"name\" : \"获取下一个任务节点\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1719994884695,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getNextNode\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"node\",\r\n    \"value\" : null,\r\n    \"description\" : \"当前节点\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"flowContext\",\r\n    \"value\" : null,\r\n    \"description\" : \"流程上下文\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"context\",\r\n    \"value\" : null,\r\n    \"description\" : \"上下文参数\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"edge\",\r\n    \"value\" : null,\r\n    \"description\" : \"流转\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"edgeIds\",\r\n    \"value\" : null,\r\n    \"description\" : \"全部流转id\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"edgeNames\",\r\n    \"value\" : null,\r\n    \"description\" : \"全部流转名称\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport org.ssssssss.script.MagicScriptContext\r\nimport \'@/flow/getNextNode\' as getNextNode;\r\nimport log;\r\n\r\nlog.info(\"传入edgeIds:{}\",edgeIds);\r\nif(is_blank(edgeIds)){\r\n    edgeIds = edge.id;\r\n    edgeNames = edge.text.value;\r\n}\r\nif(node.type == \'JqpUserTask\'){\r\n    return {\r\n        node,\r\n        edge,\r\n        edgeIds,\r\n        edgeNames\r\n    };\r\n}\r\nif(node.type == \'JqpEnd\'){\r\n    return {\r\n        node:null,\r\n        edge,\r\n        edgeIds,\r\n        edgeNames\r\n    };\r\n}\r\nif(node.type == \'JqpCondition\'){\r\n    let nextEdges = flowContext.edgeMap[node.id];\r\n    //nextEdges\r\n    let nextEdge = null;\r\n    for(index,edge in nextEdges){\r\n        if(edge.properties.checkType == \"表达式\"){\r\n            let magicScriptContext = new MagicScriptContext();\r\n            let flag = magicScriptContext.eval(edge.properties.checkConfig,context);\r\n            if(flag){\r\n                nextEdge = edge;\r\n                break;\r\n            }\r\n        }else if(edge.checkType == \"magicApi\"){\r\n            let flag = magic.execute(\"post\",edge.properties.checkConfig,context);\r\n            if(flag){\r\n                nextEdge = edge;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    if(nextEdge == null){\r\n        return {\r\n            node:null,\r\n            edge,\r\n            edgeIds,\r\n            edgeNames\r\n        };\r\n    }\r\n    return getNextNode(flowContext.nodeMap[nextEdge.targetNodeId],flowContext,context,nextEdge,edgeIds+\",\"+nextEdge.id,edgeNames+\",\"+nextEdge.text.value)\r\n}\r\n\r\nreturn {\r\n    node:null,\r\n    edge,\r\n    edgeIds,\r\n    edgeNames\r\n};'),('magic-api/function/流程/获取候选人.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"89785c844db44acab41c4f3b111e8c13\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1761a7c600fd49088232dc2c96cfc70e\",\r\n  \"name\" : \"获取候选人\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1719884076932,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getCandidateUserIds\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"task\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"flow_instance\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"context\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport magic;\r\n\r\nlet properties = task.properties;\r\nlet userType = properties.userType;\r\n\r\nif(userType == \"提交人审核\"){\r\n    return flow_instance.create_user_id;\r\n}\r\nif(userType == \"主管\"){\r\n    //第几级主管\r\n    let depLevel = properties.devLevel;\r\n    return null;\r\n}\r\nif(userType == \"角色\"){\r\n    //角色编号\r\n    let roleCodes = properties.roleCodes;\r\n\r\n    return db.select(\"\"\"\r\n        select distinct u.id from jqp_role r \r\n        left join jqp_user u on find_in_set(r.id,u.role_ids) > 0 \r\n        where find_in_set(r.code,#{roleCodes}) > 0\r\n    \"\"\").map(item->item.id).join(\",\");\r\n\r\n}\r\nif(userType == \"通过接口获取\"){\r\n    let userApi = properties.userApi;\r\n    return magic.execute(\"post\",userApi,context).join(\",\");\r\n}\r\nreturn null;'),('magic-api/task/', 'this is directory');
